def resolve_prompt_module(name):
    mapping = EXPORTS.get(name)
    if mapping is None:
        return import_module(name)
    return SimpleNamespace(**{key: getattr(import_module('fashion_recommendation_v2.prompts.' + group), symbol)
                              for key, (group, symbol) in mapping.items()})
